1	package net.officefloor.hq.app.projects;
2	
3	import java.util.List;
4	import net.officefloor.hq.app.Audit;
5	import org.springframework.jdbc.core.JdbcTemplate;
6	import org.springframework.stereotype.Service;
7	import org.springframework.transaction.annotation.Transactional;
8	
9	/**
10	 * Business logic for projects. The list view joins each project to its client to surface the
11	 * client's NAME (the UI shows names, not ids). The join reads the {@code clients} table via SQL so
12	 * the feature stays self-contained and does not import the clients feature's Java types. Deleting a
13	 * project removes its row and records an audit entry so the action can be checked later. Archiving a
14	 * project keeps the row but tucks it away: it drops off the default list and reappears only when the
15	 * caller asks to include archived ones.
16	 */
17	@Service
18	public class ProjectService {
19	
20	    private final ProjectRepository repository;
21	    private final JdbcTemplate jdbc;
22	    private final Audit audit;
23	
24	    public ProjectService(ProjectRepository repository, JdbcTemplate jdbc, Audit audit) {
25	        this.repository = repository;
26	        this.jdbc = jdbc;
27	        this.audit = audit;
28	    }
29	
30	    @Transactional(readOnly = true)
31	    public List<ProjectView> list() {
32	        return list(false);
33	    }
34	
35	    /**
36	     * A project's budget position: the budget set on it, how much has been invoiced against it (the
37	     * sum of its invoice amounts, read via SQL so the feature stays self-contained), and what is left
38	     * (budget minus invoiced). The invoiced sum reads the {@code invoices} table directly rather than
39	     * importing the invoices feature's Java types.
40	     */
41	    @Transactional(readOnly = true)
42	    public ProjectBudgetView budgetFor(Long projectId) {
43	        java.math.BigDecimal budget = jdbc.queryForObject(
44	                "SELECT budget FROM projects WHERE id = ?", java.math.BigDecimal.class, projectId);
45	        java.math.BigDecimal invoiced = jdbc.queryForObject(
46	                "SELECT COALESCE(SUM(amount), 0) FROM invoices WHERE project_id = ?",
47	                java.math.BigDecimal.class, projectId);
48	        return new ProjectBudgetView(budget, invoiced, budget.subtract(invoiced));
49	    }
50	
51	    /**
52	     * List projects with their client's name. Archived projects are tucked away: they are omitted
53	     * unless {@code includeArchived} is true (how the UI's "show archived" toggle reveals them).
54	     */
55	    @Transactional(readOnly = true)
56	    public List<ProjectView> list(boolean includeArchived) {
57	        return list(includeArchived, null);
58	    }
59	
60	    /**
61	     * List projects with their client's name, optionally narrowed to those carrying a given tag (the
62	     * UI's "filter by tag" picker). A null {@code tagId} means no tag filter — list every project the
63	     * archived flag allows. The join to {@code project_tags} reads the tag link via SQL so the feature
64	     * stays self-contained and does not import the tags feature's Java types.
65	     */
66	    @Transactional(readOnly = true)
67	    public List<ProjectView> list(boolean includeArchived, Long tagId) {
68	        return list(includeArchived, tagId, null);
69	    }
70	
71	    /**
72	     * List projects with their client's name, optionally narrowed to a single lifecycle status (the
73	     * UI's "filter by status" picker: ACTIVE, ON_HOLD or FINISHED). A null {@code status} means no
74	     * status filter — list every project the archived and tag filters allow.
75	     */
76	    @Transactional(readOnly = true)
77	    public List<ProjectView> list(boolean includeArchived, Long tagId, String status) {
78	        StringBuilder sql = new StringBuilder(
79	                "SELECT p.id, p.name, p.client_id, p.status, c.name AS client_name "
80	                        + "FROM projects p JOIN clients c ON p.client_id = c.id ");
81	        List<Object> args = new java.util.ArrayList<>();
82	        if (tagId != null) {
83	            sql.append("JOIN project_tags pt ON pt.project_id = p.id AND pt.tag_id = ? ");
84	            args.add(tagId);
85	        }
86	        List<String> conditions = new java.util.ArrayList<>();
87	        if (!includeArchived) {
88	            conditions.add("p.archived = FALSE");
89	        }
90	        if (status != null) {
91	            conditions.add("p.status = ?");
92	            args.add(status);
93	        }
94	        if (!conditions.isEmpty()) {
95	            sql.append("WHERE ").append(String.join(" AND ", conditions)).append(' ');
96	        }
97	        sql.append("ORDER BY p.id ASC");
98	        return jdbc.query(sql.toString(),
99	                (rs, i) -> new ProjectView(rs.getLong("id"), rs.getString("name"),
100	                        rs.getLong("client_id"), rs.getString("client_name"),
101	                        rs.getString("status")),
102	                args.toArray());
103	    }
104	
105	    @Transactional
106	    public ProjectView create(String name, Long clientId, String status) {
107	        if (name == null || name.isBlank()) {
108	            throw new IllegalArgumentException("A project requires a name");
109	        }
110	        if (clientId == null) {
111	            throw new IllegalArgumentException("A project requires a client");
112	        }
113	        // Default to ACTIVE when the caller doesn't pick a status, matching the column default.
114	        String projectStatus = (status == null || status.isBlank()) ? "ACTIVE" : status;
115	        Project project = new Project();
116	        project.setName(name);
117	        project.setClientId(clientId);
118	        project.setStatus(projectStatus);
119	        Project saved = repository.save(project);
120	        String clientName = jdbc.queryForObject(
121	                "SELECT name FROM clients WHERE id = ?", String.class, clientId);
122	        return new ProjectView(saved.getId(), saved.getName(), clientId, clientName,
123	                saved.getStatus());
124	    }
125	
126	    @Transactional
127	    public List<ProjectView> delete(Long id) {
128	        if (id == null) {
129	            throw new IllegalArgumentException("A project id is required to delete");
130	        }
131	        repository.deleteById(id);
132	        audit.record("PROJECT_DELETED id=" + id);
133	        return list();
134	    }
135	
136	    /**
137	     * Archive a project: keep the row but flag it so it drops off the default lists (the main project
138	     * list and the client's page). Records an audit entry so the action can be checked later, and
139	     * returns the projects that remain visible.
140	     */
141	    @Transactional
142	    public List<ProjectView> archive(Long id) {
143	        if (id == null) {
144	            throw new IllegalArgumentException("A project id is required to archive");
145	        }
146	        jdbc.update("UPDATE projects SET archived = TRUE WHERE id = ?", id);
147	        audit.record("PROJECT_ARCHIVED id=" + id);
148	        return list();
149	    }
150	}
